// 3 kaynaktan gelen verileri tek bir listede birleştir
const ideas = [];

// Input 0: Google Trends
if ($input.all()[0]) {
  const trendsData = $input.all()[0].json;
  if (trendsData && trendsData.default && trendsData.default.trendingSearchesDays) {
    trendsData.default.trendingSearchesDays[0].trendingSearches.forEach(t => {
      ideas.push({
        source: 'Google Trends TR',
        title: t.title.query,
        snippet: t.title.query + ' - Türkiye gündeminde',
        traffic: t.formattedTraffic
      });
    });
  }
}

// Input 1: Perplexity
if ($input.all()[1]) {
  const perplexityData = $input.all()[1].json;
  if (perplexityData && perplexityData.choices) {
    const content = perplexityData.choices[0].message.content;
    const lines = content.split('\n').filter(l => l.trim().length > 5);
    lines.forEach(line => {
      ideas.push({
        source: 'Perplexity',
        title: line.replace(/^[\d\.\-\*\s]+/, '').trim().substring(0, 120),
        snippet: line.trim()
      });
    });
  }
}

// Input 2: RSS Feed
if ($input.all()[2]) {
  const rssData = $input.all()[2].json;
  if (rssData && rssData.items) {
    rssData.items.forEach(item => {
      ideas.push({
        source: 'RSS - ' + (rssData.feedTitle || 'Sektörel Blog'),
        title: item.title,
        snippet: item.summary || item.content || item.title
      });
    });
  }
}

// Dedup ve temizle
const seen = new Set();
const unique = ideas.filter(i => {
  const key = i.title.toLowerCase().trim();
  if (seen.has(key) || key.length < 5) return false;
  seen.add(key);
  return true;
});

return unique.map(i => ({ json: i }));

// Havuzdan gelen fikirleri haftalık takvime dağıt
const allIdeas = $input.all().map(i => i.json);

const dayMap = {
  'Pazartesi': 'sektörel_gündem',
  'Salı': 'işletme_ipucu',
  'Çarşamba': 'vaka|nasıl_yapılır',
  'Perşembe': 'araç|rakamlarla',
  'Cuma': 'kontrol|soru_cevap',
  'Cumartesi': 'işletme_ipucu|perde_arkası'
};

const weeklyPlan = [];
const used = new Set();

for (const [day, categories] of Object.entries(dayMap)) {
  const allowedCats = categories.split('|');
  const match = allIdeas.find(i => allowedCats.includes(i.kategori) && !used.has(i.başlık));

  if (match) {
    used.add(match.başlık);
    weeklyPlan.push({
      day: day,
      kategori: match.kategori,
      başlık: match.başlık,
      açı: match.açı,
      hedef_kitle: match.hedef_kitle || 'genel',
      skor: match.skor
    });
  }
}

// Eksik günleri en yüksek skorlu fikirlerle doldur
if (weeklyPlan.length < 6) {
  const remaining = allIdeas.filter(i => !used.has(i.başlık));
  remaining.sort((a, b) => (b.skor || 0) - (a.skor || 0));

  const emptyDays = Object.keys(dayMap).filter(d => !weeklyPlan.find(p => p.day === d));
  emptyDays.forEach((day, idx) => {
    if (remaining[idx]) {
      weeklyPlan.push({
        day: day,
        kategori: remaining[idx].kategori,
        başlık: remaining[idx].başlık,
        açı: remaining[idx].açı,
        hedef_kitle: remaining[idx].hedef_kitle || 'genel',
        skor: remaining[idx].skor
      });
    }
  });
}

return weeklyPlan.map(p => ({ json: p }));

// OpenAI'dan gelen JSON array'i parse et ve her postu ayrı item olarak döndür
const response = $input.first().json;
let posts = [];

try {
  // response.message.content veya doğrudan response içinde olabilir
  let content = response.message?.content || response.choices?.[0]?.message?.content || JSON.stringify(response);

  // JSON array'i bulmaya çalış
  const match = content.match(/\[[\s\S]*\]/);
  if (match) {
    posts = JSON.parse(match[0]);
  }
} catch (e) {
  // Fallback: tek post olarak işle
  posts = [{
    day: 'Pazartesi',
    category: 'işletme_ipucu',
    post: String(response.message?.content || response).substring(0, 400),
    imageIdea: '',
    cta: ''
  }];
}

return posts.map(p => ({ json: p }));

// Bugünün gününü Türkçe olarak belirle
const days = ['Pazar', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi'];
const today = days[new Date().getDay()];

// Pazar günü paylaşım yok
if (today === 'Pazar') {
  return [];
}

return [{ json: { today: today } }];

const posts = $input.all().map(i => i.json);

// Son 7 günün verisini filtrele
const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

const recentPosts = posts.filter(p => {
  if (!p.yayın_tarihi) return false;
  return new Date(p.yayın_tarihi) >= oneWeekAgo;
});

const totalViews = recentPosts.reduce((sum, p) => sum + (parseInt(p.görüntüleme) || 0), 0);
const totalReactions = recentPosts.reduce((sum, p) => sum + (parseInt(p.tepki) || 0), 0);

// Kategori bazında
const byCategory = {};
recentPosts.forEach(p => {
  const cat = p.kategori || 'diğer';
  if (!byCategory[cat]) byCategory[cat] = { count: 0, views: 0 };
  byCategory[cat].count++;
  byCategory[cat].views += (parseInt(p.görüntüleme) || 0);
});

return [{
  json: {
    weekStart: oneWeekAgo.toISOString().split('T')[0],
    totalPosts: recentPosts.length,
    totalViews: totalViews,
    totalReactions: totalReactions,
    avgViews: recentPosts.length > 0 ? Math.round(totalViews / recentPosts.length) : 0,
    byCategory: byCategory,
    posts: recentPosts
  }
}];

const items = $input.all();
let text = "Bugünün Gündem Başlıkları:\n";

items.slice(0, 15).forEach((item, index) => {
  text += (index + 1) + ". " + item.json.title + "\n";
});

return [{ json: { trendData: text } }];

const response = $input.first().json;
let posts = [];

const content = response.text || response.data || response.message?.content || JSON.stringify(response);
const match = content.match(/\[[\s\S]*\]/);

if (match) {
