const emoji = { isletme_ipucu: '💡', sektorel_gundem: '📌', vaka: '📊', nasil_yapilir: '📋', arac: '🛠', rakamlarla: '📈', kontrol: '✅', soru_cevap: '❓', hata: '⚠️' };

const today = new Date().toLocaleDateString('tr-TR', { weekday: 'long', day: 'numeric', month: 'long' });

let message = 'ErgeneAI | Günlük Sektör Özeti | ' + today + '\n\n';

posts.forEach((p, i) => {
  const e = emoji[p.category] || '📝';
